<template><section class="manager"><header><div><h3><PosIcon name="tag" size="20" /> Clinical Dispensing Labels</h3><p>Label data is supplied by the backend and can be printed after dispensing.</p></div><button class="btn-primary" @click="printLabel"><PosIcon name="printer" size="14" /> Print label</button></header><p v-if="loading" class="state">Loading label data…</p><p v-else-if="error" class="state error">{{ error }}</p><p v-else-if="!labels.length" class="state">No dispensing labels are available.</p><div v-else class="labels"><article v-for="label in labels" :key="label.id"><strong>{{ label.patient_name }}</strong><span>{{ label.drug_name }} · Qty {{ label.quantity }}</span><small>{{ label.directions }}</small></article></div></section></template>
<script setup>
import { onMounted,ref } from 'vue'; import { PosIcon } from '@pos/ui'; import { useApi } from '../../../../apps/pos/src/composables/useApi.js'
const emit=defineEmits(['notification']); const api=useApi(); const labels=ref([]); const loading=ref(true); const error=ref(''); onMounted(async()=>{try{const data=await api.get('/api/v1/pharmacy/labels');labels.value=data.items??[]}catch{error.value='Dispensing labels could not be loaded. Please contact your administrator.'}finally{loading.value=false}}); function printLabel(){if(!labels.value.length){emit('notification',{message:'There are no labels ready to print',type:'info'});return}window.print();emit('notification',{message:'Dispensing labels sent to the printer',type:'success'})}
</script>
<style scoped>.manager{display:flex;flex-direction:column;gap:16px}header{display:flex;justify-content:space-between;align-items:flex-start}h3{display:flex;align-items:center;gap:8px;margin:0;color:#1e293b}header p{margin:4px 0;color:#64748b;font-size:12px}.btn-primary{display:inline-flex;align-items:center;gap:6px;padding:8px 11px;border:0;border-radius:6px;background:#0284c7;color:#fff;font-size:11px;font-weight:700;cursor:pointer}.state{padding:24px;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;text-align:center;font-size:12px}.state.error{border-color:#fecaca;color:#b91c1c}.labels{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:10px}.labels article{display:flex;flex-direction:column;gap:6px;padding:14px;border:1px solid #e2e8f0;border-radius:8px}.labels span,.labels small{color:#64748b;font-size:11px}</style>
